##########
import json,time
from pathlib import Path as FilePath
from spell.lang import functions as api
from spell.lang.constants import *
from spell.lang.modifiers import *
from spell.lib.exception import DriverException
observed={'calls':[],'observations':[],'fixtures':[]}
def save():FilePath('observed.json').write_text(json.dumps(observed,indent=2))
def call(name,*args,**options):
    row={'function':name,'args':repr(args),'options':repr(options)}
    observed['calls'].append(row);save()
    try:
        options.setdefault('HandleError',False);options.setdefault('PromptUser',False)
        value=getattr(api,name)(*args,**options)
        row.update(returned=repr(value),return_type=type(value).__name__);return value
    except Exception as error:
        row.update(error_type=type(error).__name__,error=str(error));raise
    finally:save()
def equal(actual,expected):
    observed['observations'].append(dict(actual=actual,expected=expected));save()
    assert actual==expected,(actual,expected)
def rejects(operation):
    try:operation()
    except DriverException:pass
    else:raise AssertionError('Expected DriverException')
def fixture(action,**values):
    token=str(time.monotonic_ns());request=dict(token=token,action=action,**values)
    temporary=FilePath('fixture-request.tmp');temporary.write_text(json.dumps(request));temporary.replace('fixture-request.json')
    reply=FilePath('fixture-'+token+'.json');deadline=time.monotonic()+5
    while not reply.exists():
        assert time.monotonic()<deadline,'Fixture timeout';time.sleep(.01)
    result=json.loads(reply.read_bytes());assert 'error' not in result,result
    observed['fixtures'].append(dict(request=request,response=result));save();return result
def golden(image='reference',**options):equal(call('CreateGoldenImage','GENERIC',image,**options),True)
def lookup(image='reference',**options):
    return call('MemoryLookup',Image=image,Type='TM',Source='GENERIC',**options)

from types import MethodType
from spell.lib.registry import REGISTRY
from spell.lib.adapter.constants.core import KEY_SEPARATOR
interface=REGISTRY['TC']
original={name:getattr(interface,name) for name in ('_sendList','driverUpdateActionList','driverBeforeAction','driverPerformAction','driverAfterAction')}
original_single=interface._sendCommand
observed['driver']=[]
pending=[]
state={'cursor':0,'interrupted':False,'allow_resume':True}

def event(action,**values):
    observed['driver'].append(dict(action=action,cursor=state['cursor'],**values));save()

def continue_group(config):
    while state['cursor']<len(pending):
        item=pending[state['cursor']]
        if not original_single(item,config):return False
        event('command-completed',name=item.name())
        state['cursor']+=1
    return True

def injection(self,items,config=None):
    event('injection',members=[item.name() for item in items])
    if pending:
        assert [item.name() for item in items]==[item.name() for item in pending]
        return continue_group(config)
    pending.extend(items);state['config']=config
    while state['cursor']<1:
        item=pending[state['cursor']]
        assert original_single(item,config)
        event('command-completed',name=item.name());state['cursor']+=1
    state['interrupted']=True
    event('driver-interruption')
    raise DriverException('Extension fixture interruption before next command')

def choices(self,options,exception=None):
    assert state['interrupted'] and state['config'][OnFailure]&RESUME
    event('choices',standard=list(options))
    return list(options)+['Z'+KEY_SEPARATOR+'Resume pending driver commands']

def before(self,code):event('before',code=code)
def action(self,code):
    assert code=='Z';event('perform',code=code)
    if not state['allow_resume']:return [False,False]
    return [False,continue_group(state['config'])]
def after(self,code):event('after',code=code)

for name,method in (('_sendList',injection),('driverUpdateActionList',choices),
    ('driverBeforeAction',before),('driverPerformAction',action),('driverAfterAction',after)):
    setattr(interface,name,MethodType(method,interface))
fixture('feed',enabled=True)

try:
    equal(call('Send',group=['CMD1','CMD2','CMD3'],Confirm=False,Wait=False,HandleError=True,PromptFailure=True,OnTrue=NOACTION,OnFalse=NOACTION,OnFailure=RESUME),True)
    equal(state['cursor'],3)
finally:
    for name,method in original.items():setattr(interface,name,method)

FilePath('result.json').write_text(json.dumps({'completed':True}))

